; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; main.bas 4: StdIO.PutStr "cols "
			dw fn_stdio_putstr, str0

			; main.bas 5: StdIO.PutInt StdIO.Cols()
			dw fn_stdio_cols, var_stdio_cols_cols
			dw kw_vtov, var_stdio_cols_cols, tmp0
			dw fn_stdio_putint, tmp0

			; main.bas 6: StdIO.NewLine
			dw fn_stdio_newline

			; main.bas 7: StdIO.PutChar 65
			dw fn_stdio_putchar, lit_65

			; main.bas 8: StdIO.PutChar 66
			dw fn_stdio_putchar, lit_66

			; main.bas 9: StdIO.NewLine
			dw fn_stdio_newline

			; main.bas 10: If StdIO.CanPosition Then Print "can position" Else Print "stream"
			dw kw_printstrvar, str1
			dw kw_printnl
			dw if1_e_go
if1_1:
			dw kw_printstrvar, str2
			dw kw_printnl
if1_e:

			; main.bas 11: Print System.Platform; " ticks/s "; System.TicksPerSecond
			dw kw_printstrvar, str4
			dw kw_printnl

			; main.bas 12: StdIO.PutStr "name? "
			dw fn_stdio_putstr, str5

			; main.bas 13: StdIO.GetLine s
			dw fn_stdio_getline, var_s

			; main.bas 14: StdIO.PutStr "hi " & s
			dw kw_strcpy, stmp0, str6
			dw kw_strcat, stmp0, var_s
			dw fn_stdio_putstr, stmp0

			; main.bas 15: StdIO.NewLine
			dw fn_stdio_newline

			; main.bas 16: k = StdIO.GetChar()
			dw fn_stdio_getchar, var_k

			; main.bas 17: Print "key "; k; " col "; StdIO.Column()
			dw kw_printstrvar, str7
			dw kw_printint, var_k
			dw fn_stdio_column, var_stdio_column_column
			dw kw_printstrvar, str8
			dw kw_printint, var_stdio_column_column
			dw kw_printnl
			dw kw_printnl0
			dw kw_printstrvar, str9
			dw kw_waitkey
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if1_e_go:			ld sp, if1_e
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_stdio_putchar:		; sub putchar (asm keyword), StdIO.cls line 22
            pop hl		; StdIO.cls 23
            ld a, (hl)		; StdIO.cls 24
            ld ix, ntc_next		; StdIO.cls 25
            cp 13		; StdIO.cls 26
            jp z, ntc_plat_newline		; StdIO.cls 27
            jp ntc_plat_putc		; StdIO.cls 28
			ret			; end of #asm

fn_stdio_putstr:		; sub putstr (asm keyword), StdIO.cls line 33
            pop hl		; StdIO.cls 34
            ld (ntc_sptr), hl		; StdIO.cls 35
            jp ntc_printbuf		; StdIO.cls 36
			ret			; end of #asm

fn_stdio_putint:		; sub putint (asm keyword), StdIO.cls line 41
            jp kw_printint		; StdIO.cls 42
			ret			; end of #asm

fn_stdio_newline:		; sub newline (asm keyword), StdIO.cls line 47
            ld ix, ntc_next		; StdIO.cls 48
            jp ntc_plat_newline		; StdIO.cls 49
			ret			; end of #asm

fn_stdio_getchar:		; function getchar (asm keyword), StdIO.cls line 61
            pop hl              ; the result [62]
            ld (ntc_ivar), hl		; StdIO.cls 63
            ld ix, fn_stdio_getchar_got		; StdIO.cls 64
            jp ntc_plat_getkey		; StdIO.cls 65
fn_stdio_getchar_got:		; StdIO.cls 66
            ld hl, (ntc_ivar)		; StdIO.cls 67
            ld (hl), a		; StdIO.cls 68
            inc hl		; StdIO.cls 69
            ld (hl), 0		; StdIO.cls 70
			ret			; end of #asm

fn_stdio_getline:		; sub getline (asm keyword), StdIO.cls line 81
            jp kw_inputstr		; StdIO.cls 82
			ret			; end of #asm

fn_stdio_cols:		; function cols (asm keyword), StdIO.cls line 106
            pop hl		; StdIO.cls 107
            ld a, (ntc_scols)		; StdIO.cls 108
            ld (hl), a		; StdIO.cls 109
            inc hl		; StdIO.cls 110
            ld (hl), 0		; StdIO.cls 111
			ret			; end of #asm

fn_stdio_column:		; function column (asm keyword), StdIO.cls line 116
            pop hl              ; 1 based, like Locate [117]
            ld a, (ntc_curx)		; StdIO.cls 118
            inc a		; StdIO.cls 119
            ld (hl), a		; StdIO.cls 120
            inc hl		; StdIO.cls 121
            ld (hl), 0		; StdIO.cls 122
			ret			; end of #asm


; ============================================================
; Variables
; ============================================================

var_stdio_cols_cols:			dw 0
			db 40			; capacity
var_s:			ds 41
var_k:			dw 0
var_stdio_column_column:			dw 0
tmp0:			dw 0
			db 255			; capacity
stmp0:			ds 256

; numbers passed by address (read only)
lit_65:			dw 65
lit_66:			dw 66

; ============================================================
; Strings
; ============================================================

str0:			db "cols ", 0
str1:			db "can position", 0
str2:			db "stream", 0
str3:			db "CPC firmware", 0
str4:			db "CPC firmware ticks/s 300", 0
str5:			db "name? ", 0
str6:			db "hi ", 0
str7:			db "key ", 0
str8:			db " col ", 0
str9:			db "Press a key", 0
str10:			db 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
ntc_next:	jp 0
kw_stop:		jp 1
ntc_xn:		jp 2
kw_vtov:		jp 48
kw_strcpy:	jp 122
kw_strcat:	jp 124
ntc_printbuf:	jp 128
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
kw_inputstr:	jp 141
ntc_plat_putc:	jp 308
ntc_plat_newline:	jp 309
ntc_plat_getkey:	jp 310
kw_waitkey:	jp 348
NTC_RJ_N	equ 16		; entries
ntc_csp	equ #8800		; ROM data
ntc_curx	equ #8910		; ROM data
ntc_ivar	equ #8814		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_scols	equ #8912		; ROM data
ntc_sptr	equ #880E		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)


; the start code (Library: ROM): run once, then the arrays go over it
ntc_rj_drop:
; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			IF (ntc_bss >= 32768) && (ntc_bssfrom <= 16384)	; fwdref-ok
			ld hl, ntc_bssfrom		; (the end of the program - or this start code, which tables may go over)
			ELSE
			ld hl, ntc_free
			ENDIF
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0
ntc_rj_dropend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			SAVEAMSDOS "CONSOLE.BIN", ntc_start, ntc_end - ntc_start, ntc_start
